#!/usr/bin/env python3
"""Cross-cutting dimensions: one reviewer each, repository-wide. Writes
STATE/dims.json, a prompt per dimension, the re-run groups and args.json (the
Workflow input). Run after units.py: REVIEW_DATE=YYYY-MM-DD review/dims.py

Per round, edit: the missions that name what is new, PREV (the last review),
FABLE (which reviewers run on Fable; the rest run on Opus) and STATE/context.md
(what changed since the last review: one paragraph every reviewer reads)."""
import json, os, subprocess
from cfg import BIN as B, DATE, REPO, REPRO, STATE as R, WORK as W

PREV = dict(date='2026-10-26', commit='7bd7c2ff0')
GROUPS = 6
D = []


def d(key, title, mission): D.append(dict(key=key, title=title, mission=mission))


PROBE_NOTE = f"""Probe discipline: put each program in {W}/work/<your key>/NN_name.gx. A probe that never reaches the code path proves nothing: an expression fuses only inside a lambda body that is called (check `graphix-fuzz run` fusion stats: fused>0), and a multi-cycle behaviour needs inputs that change over cycles (a timer `sys::time::timer(duration:10.ms, true)`, or a counter `let n = 0; n <- clk ~ n + 1`). Agreement between engines on a WRONG answer is still a bug: decide the intended value from CLAUDE.md first, then compare."""
d('x-engine-firing','Adversarial semantic probes: firing, bottom, select, sampling',f"""Write and RUN adversarial Graphix programs against the semantics in CLAUDE.md section "The semantics both engines implement" (long form: design/dense_delivery.md, representable_bottom.md, organic_firing.md): bottom is dense (Fired/Stale/FreshBottom/StaleBottom; a standing bottom re-delivers StaleBottom and never re-fires consumers; bottomness ORs over consumed productions); organic firing (a node fires iff a consumed input fires; nothing stores a previous value or selection to decide a tag); every value is bottom before its program's first cycle and a value that leaves bottom fires, so a constant fires once, in a birth (a root's first cycle, a seq step's run), and stands stale everywhere else: there is NO init rule beside that; bottom scrutinee => bottom select with no stored-selection ride of any kind; arms consulted top-down, structure then guard, and a consulted guard whose channel is bottom makes the selection undecidable; strict && / || (false && bottom = bottom); connect `<-` lands next cycle, several writes to one variable in a cycle queue for the next (a level's replaces); a value made later in the cycle reaches an earlier reader next cycle and none runs twice in a cycle; never() arms; `e ~ v` banks one trigger, `~!` is strict; uniq/filter/hold as cadence tools.
Run every probe with `{B}/graphix-fuzz check` (node-walk vs JIT vs images vs parallel vs pruned) AND print its per-cycle values with `{B}/graphix --no-cache` and `{B}/graphix --no-cache --no-fusion`, and compare with what the rules say the program must print, cycle by cycle: the fuzzer compares traces between engines and is blind to a bug both share, so hand-check cadence. Aim for 30+ distinct probes, each built to break one rule; put the select/arith logic inside lambda bodies so the JIT path is exercised. {PROBE_NOTE}""")
d('x-sleep-wake','Bind-driven bodies, sleep and wake (ruled 2026-11-11/12): adversarial probes',f"""Read design/bind_driven_bodies.md, design/sleep_and_wake.md, design/async_sleep_outputs.md. The rules, rebuilt this month: entering a select arm, a guard, a collection slot or a function activation is not an event, and neither is waking one; nothing fires in a body but its binds (a pattern bind, a slot's element, a formal) and the captures that fire while it runs; nothing is kept for a body that does not run: no catch-up, no first-entry constants, in either engine; a guard runs wherever its arm's pattern admits the value and sleeps otherwise. Sleep is pause, not reset: state survives a body's sleep; a wake is a resume, never a rebirth, and fires nothing for anyone; a resumed body recomputes from the world as it stands, reading standing values STALE; what it recomputes carries Tag::MOVED, which tells a consumer to recompute and is an event to NO reader, inside the body or outside it; a binding something writes keeps the value it holds; sleep state is local; a sleep aborts an async call in flight (one not cancel-safe finishes, unanswered) and the wake restarts nothing; a seq machine's run is aborted by its arm's sleep. Hunt for: anything that fires at an arm's entry or wake (a constant, a connect with a constant right side, an effect call, a counter); a MOVED value that a `~`, a connect, a count/uniq/once, a seq trigger, an effect builtin or an Io call treats as an event; a value that is NOT recomputed at a wake and stays stale-wrong (a capture that changed while asleep, read through a closure, a reference, a struct field, a nested select, a collection slot); state lost across a sleep; differences between a first entry in the program's first cycle and a later one; nested arms waking in one cycle; the same shapes inside collection slots and recursive activations. Compare node-walk vs JIT, pruned vs unpruned, forked vs serial, and by hand against the rules. Aim for 40+ probes. {PROBE_NOTE}""")
d('x-engine-collections','Adversarial semantic probes: collections, kernels, tail loops, arithmetic edge cases, parallel loops',f"""Write and RUN adversarial Graphix programs against the JIT/fusion paths: array/list/map HOFs (see the stdlib array/list/map .gxi for names) nested inside each other and inside lambdas; List ops and list patterns `[<h, rest..>]`; slice patterns with rest binds; tail recursion (stateless tail loops run natively — must answer exactly what activations answer, incl. firing); collections whose source changes size across cycles (grow, shrink=delete, a bottom source), a slot's element as the only thing that fires in its body (entering a slot is not an event), map-family loops large enough to be chunked by par_loop (10k-100k elements) under GRAPHIX_PAR=force and off; checked arithmetic (+? -? *? /? %?) vs unchecked (wrapping) at i64::MIN/MAX, -1, 0 divisors, small int types and casts (a cast to an integer type holds the value exactly or is an InvalidCast), float NaN/inf/-0.0 ordering (NaN == NaN, below every number), decimal; indexing/slicing out of bounds and negative bounds; string ops on multi-byte UTF-8. Run every probe with `{B}/graphix-fuzz check` and compare the printed value with what CLAUDE.md says. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-engine-seq-errors','Adversarial semantic probes: seq/seqq, catch/?/$, queued calls',f"""Write and RUN adversarial Graphix programs against: seq/seqq blocks (design/seq_blocks.md, dependency_summaries.md: a machine node, every statement a step; a step sees the world as it stood at its entry (seqq: at enqueue); `live(e)` reads live; `until`, `try {{ }} with(e) {{ }}`, `abort(e)`, `flush(e)`; a call a step makes is a fresh call at every run; a run aborted by its arm's sleep; every name a lowering binds starts with `#`; `graphix --expand` prints the lowered machine); error handling (design/catch.md: `?` with/without a covering `catch`, `$`, checked arithmetic's ArithError, handlers follow the CALL chain via DynScope, a node that calls a function in a later cycle builds the call under the Scope it was given); queued calls (design/queue_fn.md). Run every probe with `{B}/graphix-fuzz check` and compare printed values with the intended semantics. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-seq-sampling','seq step snapshots, live(), banked sampling: adversarial probes',f"""(1) A seq step sees the world as it stood at its entry: every outer variable the seq's own text reads is sampled together when the step starts (seq) or at enqueue (seqq), or when all named inputs are present; the rule is lexical, so a function the step calls reads its own captures live; `live(e)` reads live; a bare `until ready` warns. (2) `e ~ v` banks ONE trigger however many find v absent, paid once when v arrives, including when v went bottom after an earlier value; `~!` is strict; both keep their last output while the trigger is bottom. (3) abort(e)/flush(e) racing with step completion; a run aborted by the arm's sleep. Read design/seq_blocks.md, design/dependency_summaries.md, graphix-types/src/expr/seq.rs, graphix-compiler/src/node/seq_machine.rs and node/op.rs's sampling, and the skill's seq.md. Hunt for: a variable read live where it must be snapshot (through a nested lambda, a destructured let, a reference, a module-level binding, a field access, a callee default), a snapshot taken at the wrong cycle, banked triggers paid twice or lost across sleep/wake or across a bottom v, a wake's MOVED value paying a bank, interaction with walk pruning and with fusion and images. Compare node-walk vs JIT and per-cycle output against the rules by hand. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-typecheck-generics','Type checker soundness/completeness probes: generics, inference, bounds, defaults',f"""Find type-checker unsoundness (accepts a program that then misbehaves: wrong value, runtime panic, InvalidCast where none should be possible, JIT crash) and incompleteness (refuses a valid program). Write programs that SHOULD be refused per CLAUDE.md "Typing rules that bite" and design/tvar_constraints.md and check `{B}/graphix --check` refuses them; programs that should be accepted and check they are; RUN every accepted-but-suspicious program to show the consequence. Areas: `let rec` monomorphic recursion; the value restriction (a binding something writes, a `<-` target or a `&mut`'s referent, is not generalized); a function stays generic only where a binding names it (bind::names_generic: a lambda or a read of a generalized binding no binding names is one instance); a def's declared tvars rigid in its body check (none binds to a concrete type or bottom, no two unify, none escapes into a cell outside the definition) while a call instantiates them freely; a written function type holds no union of two or more of its own bare variables, and a quantified function type stands only as a declared signature's top; a merge takes the lower of its two cells' levels; labeled defaults (a default returning an enclosing function's open type); bounds Concrete/Singleton/OneNumber/Function/Number/Discernible/Ordered/NoError; arithmetic operands of EXACTLY one type; `?`/`$` on an operand whose type is not known where written; casts incl. references; &T covariant vs &mut T invariant; throws. The skill's generics.md states these rules as checked cases: probe AROUND them. Aim for 40+ probes. {PROBE_NOTE}""")
d('x-typecheck-order','Type checker probes: argument order, widening, ambiguous members, settling, top-level inputs',f"""Ruled 2026-11-13 and since: a call's arguments are met in the order of the parameters, then the defaults it omits; nothing waits for a later argument, and no rule makes a verdict independent of that order: soundness is the bar. A variable only data positions hold widens to a decided argument wider than the ones before it; an undecided argument takes the formal as it stands, and the variables it met widen no more (callsite.rs::Widening). A type that two undecided members of a union could take goes to neither (contains.rs::AmbiguousMember), and neither does an undecided type that two decided members would decide differently (UndecidedTaker): the refusal names what to annotate. The check is typecheck0 plus the settle of every call site it recorded; a top-level input (a REPL input, a script, a dynamic module's load) is checked and run alone, and what an earlier input left open is ONE type to a later input, whose decision about it is refused; an open cell at a position at the end is refused by the check as by the build (FnType::settle_terminal). Read design/tvar_constraints.md (Settling) first. Hunt for UNSOUNDNESS first: a program the check accepts whose run then casts wrongly, panics or answers wrong because a cell was decided two ways, widened after something read it, or was left open and filled later (try: higher-order arguments, callbacks whose parameter types come from a later argument, labeled arguments out of written order, defaults, partial annotations, generic collections of lambdas, recursion, method calls through traits, values flowing through references and connects). Then incompleteness: reasonable programs refused, and whether the message names an annotation that really makes the program pass (try it). Also elaboration refusing what the check accepted: run with GRAPHIX_ELAB_AUDIT=1. Aim for 40+ probes. {PROBE_NOTE}""")
d('x-typecheck-patterns','Type checker probes: select coverage, patterns, typedefs',f"""Find type-checker unsoundness/incompleteness in select and patterns (design/select_coverage.md, or_patterns.md, distinct_composite_forms.md, the skill's select.md): select is exhaustive with no dead arms, decided by ONE walk (select.rs::Reach), with patterns inside a declared variable and `name@` captures; a type still undecided at a select's end is one unknown type, equal only to itself: an arm testing it is refused, naming the binding to annotate; a written test two undecided members of the scrutinee could take is refused (written_takers); only a select's own pattern walks keep the first member (contains_ordered); no arm may tell apart two types that share a runtime form (Type::rep_collision); slice and list patterns, or-pattern binds, struct/tuple/variant patterns, type tests over collections, guards; a `never()` arm adds nothing to a select's type; typedefs (contractive; every written name resolves; recursive types; an inferred type must be finite); never<T>(). Check with `{B}/graphix --check`, and RUN accepted programs that look unsound to show the consequence (a value reaching an arm whose pattern type it does not have; a non-exhaustive select falling through at run time). Aim for 40+ probes. {PROBE_NOTE}""")
d('x-traits-abstract','Traits, core traits and nominal abstract types: adversarial probes',f"""Read design/traits.md, design/nominal_abstract_types.md, design/abstract_cast.md and the skill's modules.md. Probe: trait declarations and impls (coherence, an impl for a union, default methods, methods as values, a trait as a parameter's type being a bounded quantifier, a trait named above its declaration, bounds on quantifiers, constructor traits); static dispatch choosing the right impl after inference; core traits (Eq/Ord/Display/Cast and the like) over user types as map keys, sort keys, in ==, in printing and in casts, including inside fused code and across an image restore, and what happens when the impl is deleted or redefined (REPL, dynamic module); nominal abstract types: `Abstract<T>` visible only where the definition is (the defining module, a public one in the .gxi, every instance of the defining body), `T as t` tag tests over unions of abstracts, one allocation per construction; an abstract crosses data (json/toml/pack, casts, sys::net) only through `impl Cast` in its defining module. Hunt for unsoundness (the payload read where the definition is not visible; two abstracts confused after a cast or a round trip; an impl found that should be hidden) and for engine divergence. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-dyn-modules','Dynamic modules: sandbox by sig imports, loads, retirement (built 2026-11-15, unsoaked): adversarial probes',f"""Read design/module_system.md and the skill's modules.md. Built this week and NOT soaked: there is no `sandbox` statement; a dynamic module's body gets an EMPTY environment (no core) plus what its sig `use`s; each load is a top-level input, checked and run alone; a loaded body's view reads its own registry first (Env::trait_def, impls_of, find_impl; LoadedBody, OwnTypes); a new source replaces the old load, and a retired load releases its types, impls, core-trait hook sites and type names with its last function. Hunt for: SANDBOX ESCAPES (a body reaching a name its sig does not import: through a type, a trait impl, a default argument, an attribute, string interpolation, a builtin name, `use` inside the body, a path with `..`, a value of function type passed in and called, core operators that need core traits); a bad source (parse error, type error, sig mismatch) taking down the host or leaving half a load; reloading while calls are in flight, while a seq runs, while an arm sleeps; values of a retired load's types still held by the host (printing, comparing, casting, sending them); leaks across many reloads (watch RSS over a few hundred reloads); impl coherence between host and load, and between two loads; engine divergence and image interaction. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-check-build','The check vs the build: what --check accepts the build must build',f"""CLAUDE.md: the check is typecheck0 plus the settle of every call site it recorded, and `--check` and the language server run it alone; elaboration (typecheck1, instances, fusion) refusing what the check accepted is a type-system bug, and so is the check refusing what a build would accept and run correctly. Generate MANY program shapes (start from the repo's own corpus: book/src/examples, stdlib .gx, the skill's fences, the run! fixtures in stdlib/graphix-tests, then mutate them: delete an annotation, swap argument order, wrap in a lambda, a select, a module, a seq) and for each compare `{B}/graphix --check` with `GRAPHIX_ELAB_AUDIT=1 {B}/graphix --no-cache` (and `--expand`): a program the check passes and the build refuses, or the reverse, is a finding, as is a different message for the same refusal. Also #[native]/#[sync]/#[pure]/#[tail_recursive] assertions: refused by the build only where they should be, and an uncalled definition is valid. Aim for 150 programs through the comparison (a small driver script, at most 2 processes at a time) and report each distinct disagreement once. {PROBE_NOTE}""")
d('x-recursion','Activations, recursion, tail loops and containment: adversarial probes',f"""Read design/activation_state.md, recursive_activations.md, tail_calls_are_calls.md, atomic_recursion.md, jit_memory.md. Every call is an activation, tail or not; the JIT runs a STATELESS tail recursion as one native loop held to the activations' answers; there is no depth limit, and containment stops the runtime for good; a function value keeps the bindings it captures alive. Probe: recursion (direct, mutual, through a HOF, through a collection callback, through a trait method, through a function-valued argument or a reference) with state in the body (counters, uniq, timers, async calls), firing through recursive activations over several cycles, deep recursion (10^4-10^6 activations: memory per activation, time, teardown, what happens at the memory cap: a clean stop or a crash), runaway recursion (must be contained, in both engines, forked and serial), a tail loop the JIT runs natively vs the same function node-walked (identical answers and firing, including on error raises and bottoms inside the loop), #[tail_recursive]; deletion of a collection slot or an arm mid-recursion; closures escaping an activation. Keep every run under the wrappers' memory caps; an OOM-KILLED reasonable program is a finding. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-refs','Place references: adversarial probes',f"""Read design/place_references.md and CLAUDE.md "References": `&e` is read-only and covariant, `&mut e` writable and invariant; references de-fuse; a reference names a place (&a[i], &s.f, &t.0, &m{{k}}), reference equality is by what they name; the referent of a `&mut` is not generalized; a closure keeps what it captures alive. Probe: writes through references to places inside collections whose shape changes, moving references with dynamic keys, a reference whose address is bottom, references stored in structs, collections, closures and passed to async builtins, references across sleep/wake (a write through one while its arm sleeps; MOVED at the wake), across a seq step's snapshot, in recursive activations, in dynamic modules, and across an image restore; aliasing (two &mut to one place; a & and a &mut); reference cycles (a struct holding a reference to itself) and what frees them (watch RSS over many cycles); type soundness (covariance of & used to write, a &mut widened). Compare node-walk vs JIT (the surrounding code should still fuse where it can), pruned vs unpruned. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-async-io','Async builtins and io: cancel safety, call modes, queued calls, streams',f"""Read design/async_sleep_outputs.md, design/queue_fn.md, design/builtins.md and stdlib sys's .gxi. A sleep aborts an async call in flight; a call that is not cancel-safe (a db op, a handshake) finishes, unanswered; a stream read's bytes go back to the stream; the wake restarts nothing; event sources (timers, idle waits, subscriptions, line readers, servers) pause while asleep. Audit every async builtin's cancel-safety and call mode against what it actually does (a read that consumed bytes before the abort IS data loss; a write half-done), replies arriving after delete, the stream types' trait impls against each other (DRY), queuefn ordering and credits, and probe with real files, pipes, processes, tcp on localhost and timers inside select arms that flip (use small timers and sys::exit to end runs). {PROBE_NOTE}""")
d('x-repl','The REPL and scripts as sequences of top-level inputs: probes',f"""Each REPL input is a top-level input: checked and run alone; a later input sees what an earlier one left open as ONE type and may not decide it; a value made by a later input reaches an earlier reader next cycle; redefining a name, a type, a trait or an impl in a later input; `-:` type lines; errors in one input must leave the session usable and leak nothing. Drive `{B}/graphix` as a REPL through a pipe or a pty with a small Python driver (see how graphix-shell/tests/shell/ and stdlib/graphix-tests/src/lang/repl_inputs.rs drive it, and book transcripts marked `,repl`), feeding sequences of inputs built to break these rules: generic bindings used at two types across inputs, a binding left undecided then used, shadowing, a function redefined while an earlier input still calls it, a `<-` from a later input to an earlier binding (and to one an earlier input called statically), modules and `use` across inputs, an input that fails halfway, Ctrl-C (interrupt) during a running input, very long inputs, input split across lines. Also scripts with an interface file beside them. Compare with the same program as one file where the rules say they agree. Aim for 30+ sessions. {PROBE_NOTE}""")
d('x-diagnostics','Diagnostics: every refusal names its site and the annotation that makes the program pass',f"""CLAUDE.md "Sound by construction": a hole in the type system is closed by a local rule that refuses and names the annotation that makes the program pass. Collect the checker's refusal messages (grep bailat!/Told::over/`annotate` in graphix-types/src/typ, graphix-compiler/src/node, select.rs, callsite.rs; design/must_reject.md lists families) and for each rule write the smallest program that triggers it, then judge the message as a Graphix author would: does it point at the right expression (line and column; run `{B}/graphix --check`), does it say what to do, and does doing exactly that make the program pass (try it)? Findings: a message that names the wrong site or the wrong binding; advice that does not work or is not expressible; an internal name or a generated variable id leaking (`#` lowered names, cell ids); the same refusal reported twice; a refusal with no position; a note that does not apply ("was decided early" beside an unrelated refusal); a warning that fires on correct code or is missing where the skill promises one (a constant right side in an arm, a constant-only effect call, a seq with no trigger in an arm, a bare `until`). Also run-time failures: are they logged under the failure target with the expression, never printed raw or lost? Aim for 50+ refusals examined. {PROBE_NOTE}""")
d('x-leaks','Leaks: memory, tasks, timers, subscriptions, types and registry entries',f"""Find resources that outlive their owner. Write long-running programs that create and destroy things every cycle or every few cycles and watch the process (RSS from /proc/<pid>/status sampled by a small driver, thread and fd counts): select arms that flip (asleep bodies keep state, deleted ones must free it), collections that grow and shrink (a deleted slot frees its nodes, its closures, its timers, its async calls), recursive activations that end, closures capturing bindings of deleted scopes, references, seq machines started and aborted, queued calls, dynamic module reloads, REPL-style redefinitions, traits/impls/types of retired loads (the registries: Env, core-trait hook sites, ABSTRACT names, DefTable, JIT code arenas/generations: design/jit_memory.md), timers, fs watches, subscriptions, tcp/http servers and clients, child processes. A steady climb over thousands of cycles with a steady workload is a finding: find what holds it (existing pins: stdlib/graphix-tests/src/lib_tests/leaks.rs; `graphix-fuzz` leakcheck in design/graphix_fuzz.md). Compare fusion on and off: JIT-owned values have their own drop paths. Keep runs under 120 s and under the memory cap. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-stack','Stack discipline: program-driven recursion without ensure_sufficient, with probes',f"""CLAUDE.md "Stack discipline": every program-driven recursion must be wrapped in `crate::stack::ensure_sufficient` (or be iterative), and the parser caps nesting. (1) Find recursive functions in graphix-types, graphix-compiler, graphix-rt, graphix-lsp, graphix-shell and stdlib that recurse on program- or value-controlled depth without the guard. (2) PROBE: deep programs (nested parens/arrays/structs/lambdas/blocks/selects/patterns/types/modules/seq, long operator chains, long `let` chains building deep types, typedef chains) and deep runtime values (built recursively, then printed, compared, used as map keys, json/toml/pack round trip, sent through netidx); run `{B}/graphix --check`, `{B}/graphix --no-cache`, and with the image cache on (run twice, XDG_CACHE_HOME under your scratch dir), and `{B}/graphix fmt --stdout`. Exit 139/134 or "stack overflow" = finding; a clean error or a result = fine. Existing pins: graphix-shell/tests/deep_nesting.rs, graphix-compiler/tests/deep_drop.rs. {PROBE_NOTE}""")
d('x-image','Session images: warm/cold equivalence and corrupted-cache robustness, with probes',f"""Read design/program_image.md and CLAUDE.md "Session images", then probe: (1) cold vs warm equivalence over many program shapes (run `{B}/graphix` WITHOUT --no-cache twice with a fresh XDG_CACHE_HOME per program; also `graphix-fuzz check`), including programs whose instance bodies decode lazily, fused kernels, traits, modules, abstract types, references; (2) staleness: edit a source file a program reads (a module file, its .gxi) between runs, change GRAPHIX_MODPATH or flags — the program entry must re-verify and never run stale code; (3) robustness: corrupt the cached .img (truncate, bit-flip, zero, append, swap) and rerun — it must start cold silently, never crash/hang/misbehave; (4) review decode paths for unchecked lengths/offsets/ordinals/recursion. {PROBE_NOTE}""")
d('x-unsafe','Unsafe code audit (repository-wide)',"""Audit every `unsafe` block, fn, impl and trait in the workspace (excluding generated tree-sitter code): the safety contract, whether every caller upholds it, safe fns exposing UB, Send/Sync impls, raw pointers into Values across the JIT boundary (refcount balance on every path), loans extended by raw pointers (core-trait value hooks, KERNEL_ABORT/KERNEL_ENV, ParLoan, branch views) and what mem::forget or unwinding does to them, mmap'd or read image files, transmutes and pointer casts, extern "C" helpers that can unwind, uninitialized memory, static mut, the runtime heap and activation layout. Report real or likely unsoundness with the concrete scenario; demonstrate where a program can reach it.""")
d('x-panics','Panics and aborts reachable from external input',f"""Find panics/aborts reachable from external input: Graphix source text, .gxi interfaces, the image cache file, graphixfmt.json, packages.toml, LSP client messages, netidx values, HTTP requests/responses, files read via sys::fs, process output, TUI/GUI events, and run-time values flowing into builtins (huge sizes, negative counts, NaN durations, invalid regexes/format strings, huge repeat counts). Look for unwrap/expect/indexing/slicing/unreachable!/panic!/assert!/overflow/`as` truncation; determine what a panic does at each site (kills the runtime task? the process? silently stops a widget?). Demonstrate with the debug binaries. {PROBE_NOTE}""")
d('x-node-contract','Node trait contract audit: every Update/Apply impl',"""For every `impl ... Update for` and `impl ... Apply for` in graphix-compiler and every stdlib package, check: `refs` enumerates every child and bind id; `delete` deletes every child and unrefs every variable it ref'd, cancels timers/spawns, returns activation budget; `sleep` sleeps every owned child and sets its own slept bit where it owns skip state, stateful builtins keep state across sleep, async builtins abort calls in flight (one not cancel-safe finishes, unanswered); `typecheck0`/`typecheck1` visit every child; `typecheck0_instance` does exactly the state part; `image_encode`/`image_decode` are symmetric and capture all pre-cycle state (NOT_QUIESCENT otherwise); `emit_clif`/`fuse` consistent with update. Report each gap with the scenario; demonstrate with a program where one can reach it (a leak visible as growing memory or a stale write after delete, a wrong value after a wake).""")
d('x-builtin-effects','Builtin classification audit: EFFECT, FastCall, ORDERED, image codecs, signatures',f"""For every BuiltIn impl across stdlib/* and graphix-compiler, check EFFECT (Stateless only if a pure function of its args; Sync if it keeps state or depends on which args arrived; Async if it may produce later/never; Io for world effects at each trigger fire), compare each FastCall/IoCall entry with the eval path for edge inputs (read both; PROBE inside a lambda mapped over an array so it fuses, with `{B}/graphix-fuzz check`), EvalCachedAsync::CALLS (Fifo/Latest/Concurrent) appropriateness, ORDERED for shared in-language state, image_decode restores state, FastMemo for derived config, type-directed builtins declare 'b: Concrete, function-wrapping ones 'a: Function, and each Graphix signature (every arg and return annotated) matches the Rust side's arg parsing and result type. {PROBE_NOTE}""")
d('x-parallel','Parallel evaluation and parallel compile: races, nondeterminism, serial equivalence',f"""Read design/parallel_eval.md, design/parallel_compile.md and CLAUDE.md "Parallel evaluation". Audit and PROBE: branch views (every runtime-side effect through the view, merged in program order), plan_block independence (what a sibling publishes vs reads, ORDERED builtins, catch runs last), thread-locals/statics seen across contexts or branches, compile tasks' cell writes (tvar::decided) and join order, kernel par_loop chunks, server request forks (http::serve, rpc). PROBE with GRAPHIX_PAR=force + GRAPHIX_PAR_AUDIT=1 vs GRAPHIX_PAR=off, and GRAPHIX_TASK_AUDIT=1, GRAPHIX_FUSE_SERIAL=1 A/B, on programs with sibling writes/reads, connects, sampling, queuefn, seq machines, nested collections, error raises, external effects; repeat force runs to catch nondeterminism. {PROBE_NOTE}""")
d('x-doc-drift','CLAUDE.md, design docs and AGENTS.md vs the tree',"""Check every concrete claim in CLAUDE.md against the tree (named functions, types, files, flags, env vars, test pins exist and do what is said; the debug env var table vs the code (grep each var; find env vars the code reads that the table lacks); the project structure; the build/test commands). Check design/README.md's index against design/ and each design doc's as-built claims against the code (sample the most-cited ones: strict_fusion, sleep_and_wake, bind_driven_bodies, parallel_eval, program_image, seq_blocks, tvar_constraints, select_coverage, module_system, traits). Check AGENTS.md == `cat ~/.claude/CLAUDE.md <(printf "\\n") CLAUDE.md` byte for byte. Report each drift with the claim, where it is, and what the tree does (tag doc-drift). Line-level doc fixes in CLAUDE.md go in the doc as a list, not CRs: give the CLAUDE.md line anyway.""")
d('x-dup','Duplication across the workspace (DRY)',"""Find the most significant duplicated logic across the workspace (copy-pasted functions, parallel implementations of one algorithm, near-identical builtins, the two test harnesses graphix-package/src/test.rs vs stdlib/graphix-package-core/src/testing.rs, node-walk vs JIT helpers computing the same thing separately, image encode/decode boilerplate, gui/tui widget conversion boilerplate). Give file:line ranges of every copy, what differs (a divergence may be a bug — check and say), and the smallest unification that adds no layer. Top ~20 by payoff.""")
d('x-perf-compile','Compile-time performance: typecheck and fusion scaling, with measurements',f"""CLAUDE.md: the typechecker must stay instant. MEASURE compile cost scaling: generate families of programs at sizes N, 2N, 4N, 8N (many lets, many functions, deep generic call chains, wide unions/structs, big selects, many modules/interfaces, trait-heavy code, long seq blocks, big literals, many collection HOFs) and time `{B}/graphix --check` and `{B}/graphix --no-cache` to first output (and `GRAPHIX_PROFILE=1` for phase breakdown). Any family that grows superlinearly is a finding: find the code responsible and say why. Also time --check on the largest examples and the gui/tui stdlib. These are debug binaries: compare RATIOS, not absolute times, and repeat a measurement (the machine is shared with other review agents; noise is real). {PROBE_NOTE}""")
d('x-perf-runtime','Runtime performance: per-cycle cost scaling, with measurements',f"""MEASURE per-cycle cost scaling at run time: a cycle should cost what changed, not the program size. Families: one slot of a 10k-100k array changing per cycle under array::map/filter/fold; a map with one key changing; a deep recursion re-run; many sleeping arms; many timers; a long seq machine; a big struct with one field changing; string building; parallel eval overhead on tiny programs (GRAPHIX_PAR=auto vs off). Time with self-timing programs (sys::time / counters) or wall clock over a fixed number of cycles, at sizes N, 2N, 4N; with fusion on and off. Superlinear or O(total) where O(changed) is expected is a finding: find the responsible code. These are debug binaries (opt-level s, debug assertions): compare ratios. Keep memory well under the cap. {PROBE_NOTE}""")
d('x-formatter','Formatter and printer: round trip, idempotence, refusal',f"""CLAUDE.md "Formatter". PROBE `{B}/graphix fmt --stdout <file>` over every .gx/.gxi in the repo and ../netidx (a refusal is fine but should be rare: list them), then over adversarial inputs: comments in every legal position, attributes, docs in interfaces, long lines at the width boundary, nested lambdas, use trees with shared prefixes and globs, string delimiters and escapes, unicode, raw strings, CRLF line ends, trailing whitespace, empty files, seq/try/with/abort, or-patterns, list literals, references, typedefs with unions, numeric literal forms (hex, suffixed ints, floats like 1e10, -0.0). Check: output reparses to the same program (meaning), formatting is idempotent (fmt(fmt(x)) == fmt(x)), no comment is lost or moved to a different item, nothing is silently changed in meaning (run both versions when in doubt), the --check exit code is right. Also the canonical (non-AsWritten) printer: printed types/expressions in error messages and cast errors must reparse. {PROBE_NOTE}""")
d('x-lsp-probe','Language server: protocol-level probes',f"""Drive the real server `{B}/graphix lsp` over stdio with a small Python JSON-RPC client you write (Content-Length framing; initialize, initialized, didOpen/didChange (full and incremental), hover, definition, references, completion, documentSymbol, formatting, shutdown/exit). Probe: positions past end of line/file, UTF-16 surrogate pairs and multi-byte text before the cursor, CRLF, incremental edits that split a multi-byte char, files outside any project, a package root, a file that does not parse, rapid edits (coalescing), definition across modules, a .gxi beside a script, closing a file, unknown methods, malformed JSON. Crash, hang, wrong position or stale answer = finding. Use the existing e2e harness in graphix-shell/tests/lsp/ to learn the expected behaviour. Every process under `timeout -s KILL`. {PROBE_NOTE}""")
d('x-security','Security of code handling external input',f"""Audit code that touches the outside world for security defects: module resolvers (FilesResolver/VfsResolver path handling, `..` and symlinks, NetidxResolver loading CODE from the network — what trust is assumed?), the image cache (a cache file another user could write: permissions of $XDG_CACHE_HOME/graphix entries, a crafted image decoded into JIT machine code — is the checksum the only guard, and is that safe?), the package manager (invoking cargo, writing manifests, vendoring paths, shell injection), http client/server (header injection, unbounded bodies, slowloris), sys::process (argument quoting), sys::fs (symlink races where it matters), tls config (verification defaults), sqlite/db (injection via string building), handlebars templates (escaping), the LSP server (file URIs outside the workspace). Report each with the attack scenario; demonstrate where cheap and safe (never touch anything outside your scratch dir). {PROBE_NOTE}""")
d('x-concurrency','Concurrency in the runtime and stdlib: deadlocks, races, shutdown',f"""Audit graphix-rt and every stdlib package that spawns tasks or threads (sys net/io/process/watch/time, http, db, gui event loop, tui, the evaluation pool in branch.rs, the JIT link threads): locks held across .await or across a call back into the runtime, lock ordering, channels that can fill and block the runtime, tasks that outlive their owner (a deleted node whose task still writes), shutdown ordering (GXHandle drop, runtime exit while tasks run, 'could not send batch' style errors), interrupt (GXHandle::interrupt, Ctrl-C) during each phase, timers after delete, the activation budget under concurrency. Demonstrate with programs where possible (e.g. create and delete subscriptions/timers/processes rapidly in a select whose arm toggles; run under `timeout` and look for hangs, panics or late writes). {PROBE_NOTE}""")
d('x-prune','Walk pruning: adversarial probes',f"""Walk pruning (design/walk_pruning.md, CLAUDE.md "Walk pruning") skips what nothing marked. A block statement, a select arm body and an instance body each sit in a Prune boundary that is skipped in a cycle where nothing marked it. Every this-cycle write must mark its readers' boundaries and their ancestors. Find writes or state changes that reach a reader WITHOUT marking (a builtin that writes a variable some other way, a node that inserts into event.variables directly, polled state other than ErrorHandler, a reference write patched at delivery, a seq machine's step entry, a wake's MOVED recompute, a delivery to a reader the walk already passed (ExecCtx::deliver), a queue credit, a timer/async completion delivered into a skipped instance, image-decoded callees registering under the wrong boundary, a dynamic module recompile, a collection slot boundary). Grep for the marking calls and for writes that bypass them. PROBE: run programs with GRAPHIX_PRUNE=audit (it panics where a skip would have changed a production or published) and compare GRAPHIX_PRUNE=on vs off output cycle by cycle, with fusion on and off, GRAPHIX_PAR=off and force. Aim for 30+ probes. {PROBE_NOTE}""")
d('x-kind-markers','Kind markers and NoError: adversarial probes',f"""Composite forms (design/distinct_composite_forms.md, CLAUDE.md "Composite forms", graphix-types/src/rep.rs): tuple/struct/variant/list cells are arrays whose element 0 is a kind marker; data carries no markers (writers strip, reader casts rebuild). Also the NoError bound and the open-member rule (Type::rep_collision). Hunt: (1) code outside rep.rs/list.rs that indexes or measures a composite assuming the old layout (array::len of a tuple, element access, pattern matching in the JIT, json/toml/pack/xls/sqlite/db/netidx writers and readers, printing, Eq/Ord/hash of composites, cast of a struct from data, cast<string> of a variant); (2) a marker leaking into data (write a struct/tuple/variant/list to json/toml/pack/netidx/db/file and read it back raw); (3) data that a reader turns into a composite wrongly (a plain array with the right length cast to a tuple; a string cast to a bare variant); (4) image round trips of markers; (5) NoError: Result<'r, 'e> with 'r an error type refused; the open-member rule in unions. PROBE with {B}/graphix-fuzz check and the plain binary. Aim for 30+ probes. {PROBE_NOTE}""")
# Design reviewers: a few, on Fable, each over one whole design, not its lines.
DESIGN_OUT = """YOUR OUTPUT differs from a line reviewer's. `summary` is your design assessment, written for Eric as the architect: up to about 1,200 words of plain prose in short headed paragraphs: what the design is, what is strong and must be kept, the three to seven problems that matter most, in order, and for each what you would do and what it would cost. It goes into the review document as you write it. Each problem Eric should rule on, or that names concrete work, is ALSO a finding (at most about 12): tag structure (or risk, perf, doc-drift, test-gap where that fits), addressee eric unless the fix is clearly local, anchored at the item that embodies the design (a trait definition, a module's first item, a design doc's section heading). Evidence still matters: show each cost with a program you ran, a count, or a measurement (the number of places a new node kind must be implemented; the annotations a reasonable program needs; the lines of Rust behind one widget), and say what you compared with. Do not review line-level correctness: 149 other reviewers do that. Judge the design against its own stated goals (CLAUDE.md; Eric's principles: do not repeat yourself, no unwieldy layers of abstraction, make invalid states unrepresentable, fix root causes, complexity must pay rent, many corner-case rulings on one mechanism mean the model is in question) before judging it against other systems, and name what you would NOT change."""


def a(key, title, mission): d(key, title, mission + '\n\n' + DESIGN_OUT)


a('a-language', 'Design review: the language', f"""Review Graphix as a language design. Read the book (book/src: every chapter under core/, functions/, modules/, udt/), the graphix-lang skill and its topic files (its "rules that bite" list is the best record of what surprises authors), CLAUDE.md's semantics and typing sections, the design docs that define the semantics (dense_delivery, representable_bottom, organic_firing, bind_driven_bodies, sleep_and_wake, seq_blocks, tvar_constraints, select_coverage, traits, nominal_abstract_types, place_references, catch, queue_fn, module_system), the examples (book/src/examples), and the dogfood record of the one large external program (../netidx/design/graphix-admin.md, graphix-admin-findings.md, and the package's .gx sources). Then WRITE programs: take four or five ordinary tasks (a form with validation and a save button; a poller that retries with backoff; a table that sorts, filters and edits rows; a small protocol client over tcp on localhost; a recursive data transformation) and write each the way a competent newcomer would after reading the book, noting every place the language surprised you, refused you, or needed an annotation or an idiom (`~`, `hold`, `uniq`, `never()`, seq) to say something simple. Assess: whether the semantics follow from one model a user can hold in their head, or from a list of rulings (which of the skill's bite rules are inherent to reactive dataflow, and which are design debt with a fix); the reactive core (firing, bottom, `<-` landing next cycle, sampling, select as the only conditional, sleeping arms) against the sequential escape hatch (seq/seqq): is the boundary in the right place, and is each side complete; errors (error values, `?`, `$`, catch, bottom, logged failures: how many ways can a failure travel, and can an author tell which they have); the type system's power against its weight (structural types, unions, inference with soundness by refusal: how much annotation does ordinary code need, and are the refusals teachable); traits, abstract types and modules as the tools for large programs; what is missing that authors will reach for first; and how the design compares with its nearest relatives (synchronous languages such as Lustre and Esterel, FRP and Elm, signals in Solid/Svelte, Incremental and Bonsai, Rx) where they solved the same problem differently.""")
a('a-compiler', 'Design review: the compiler and the runtime', f"""Review the architecture of the implementation: graphix-types, graphix-compiler, graphix-rt, and how the shell, the language server and the fuzzer sit on them. Read design/architecture.md and README.md first, then final_jit_architecture, distributed_jit, strict_fusion, unified_value_abi, jit_memory, parallel_compile, parallel_eval, program_image, walk_pruning, dense_delivery, activation_state, recursive_activations, testing, graphix_fuzz; then the code's skeleton (the Update and Apply traits and their implementors, CompileCtx/ExecCtx/ExecState, the typecheck0/typecheck1 passes, the fusion gate, the image codecs, the Rt trait and its one implementation). Measure the shape: lines per module, the largest files and functions, the fan-in of the central types, and for ONE ordinary node kind and ONE builtin count every place it must be implemented or registered (update, delete, sleep, refs, typecheck0/1, emit_clif/fuse, image encode/decode, prune marks, fork plans, the fuzzer's generator) and what happens when one is forgotten (a compile error, a test failure, or a silent wrong answer). Assess: the decision that the node graph is the IR and that two engines (the node-walk and the fused cranelift kernels) implement one semantics, policed by a differential fuzzer: what that costs per feature, where the two share code and where they only share a spec, and whether the split of what fuses is stable; where invariants are held by convention, comments and debug assertions rather than by types; the layering between the static half (graphix-types) and the compiler, and what leaks across it; state and its ownership (per-node state, ExecCtx, thread-locals, process-wide statics) with parallel compile and parallel evaluation in mind; the type checker's structure (cells, levels, settle, the 5-10k-line files): can a new contributor change a typing rule safely, and what tells them they broke one; images and caching as a cross-cutting tax; build and test time as a design property; what in the design is carrying its weight and must be kept; and the order in which you would restructure, with what each step buys.""")
a('a-stdlib', 'Design review: the standard library and the builtin interface', f"""Review the standard library as a designed API and as an extension interface. Read every package's .gxi under stdlib/*/src/graphix (they are the API), the book's stdlib and ui chapters, design/builtins.md, stdlib_notes.md, collection_intrinsics.md, list_native.md, async_sleep_outputs.md, queue_fn.md, gui_updates.md, and enough of each package's Rust to see how much code stands behind a function or a widget. USE it: write three or four real small programs that cross packages (read a directory of json files, validate and aggregate them, write a toml report; a tcp line server on localhost with a sqlite or db store behind it; a tui screen with a table, a form and a status line; the same screen in the gui checked with --check) and record the friction: names you guessed wrong, argument orders that differ between siblings, a labeled argument here and a positional one there, three ways to say one thing, a missing function you had to write, an error you could not catch, a value you could not convert. Assess: consistency of naming, argument order, labels and return conventions across array, list, map and str and across the sys modules; the error convention (hot operators log and return bottom, rare functions return a catchable Error): is it applied the same way everywhere and can an author predict which they get; the collection story (arrays, native lists, maps, the traversal intrinsics, the Collection trait): overlap, gaps, cost model; io (streams, files, processes, tcp, tls, netidx, http) as one design or several; data formats and casts as the reading interface; the two ui packages: the widget model, how reactive values and callbacks reach a widget, how much Rust and how much Graphix one widget costs, what the two share and what they duplicate; the builtin interface itself (the BuiltIn trait, the effect classes, fast calls, codecs, signatures in .gxi): what a third party must know and write to add one function correctly, and what goes wrong silently if they misclassify it; what a standard library of this kind should have that is missing, and what is here that should be a separate package.""")
a('a-packages', 'Design review: modules, packages, embedding and tooling', f"""Review how Graphix programs are organised, distributed, embedded and worked on. Read design/module_system.md, nominal_abstract_types.md, netidx_extraction.md, program_image.md, formatter.md, language_server.md, the book's modules/, packages/ and embedding/ chapters and shell.md, graphix-package (the package manager: packages.toml, vendoring, standalone builds, the skeleton), graphix-derive's defpackage! and graphix-ast-pack, the shell's command line, graphix-rt's embedding surface (GXHandle, GXExt, the Rt trait), and the first package written outside this repository (../netidx graphix-package-netidx-admin and its findings ledger) as the evidence of what a third-party author meets. Try the workflow as a newcomer where it is cheap: scaffold a throwaway package in your scratch directory with the package manager, read what it generates, and trace what building and running it would do (an actual package build is a full cargo build: run at most two, each exactly under the cargo rule's lock and timeout with the throwaway copy as its directory, and none if reading answers the question). Assess: modules, interfaces (.gxi) and visibility as the tools for programs of 10k+ lines; dynamic modules and the sandbox (a body sees only what its sig imports): what trust model it actually gives, and for whom; the choice that a package is a Rust crate built by cargo into the shell: what that means for distribution, versioning, reproducibility, build time, binary size, platform support and the trust an author places in a dependency, against the alternatives (pure-Graphix packages loaded at run time, a plugin ABI, wasm); the package manager's commands and failure modes; the embedding API: what an embedder must implement, what they can observe and control, and what is hard to do (drive cycles, bound resources, sandbox a script, hot-reload); the developer loop (check time, the session image cache and when it is wrong, the formatter, the language server, error messages, the REPL); and what must exist before a stranger can build something real on Graphix, in order.""")

for i in range(1, GROUPS + 1):
    d(f'x-rerun-{i}', f"Re-run of the {PREV['date']} review repros, group {i} of {GROUPS}", f"""The previous review (design/REVIEW-{PREV['date']}.md) saved repros for its findings in design/review-{PREV['date']}/repro/. Since then a campaign fixed nearly every finding (CRs deleted; commit messages name the finding ids), and several rules were RULED differently by Eric since (CLAUDE.md and design/ hold the rules as built: bind-driven bodies and no wake catch-up, arguments met in order, sandbox by sig imports). YOUR GROUP is the list of repro files in {R}/repro-groups/g{i}.txt. For EACH file: read its header (finding id, command, expected vs observed then), find how it was resolved (`git log --format='%h %s' {PREV['commit']}..HEAD --grep='<id>'`, `cr show <id>` for a CR still open, and the finding's row in design/REVIEW-{PREV['date']}.md), then RUN it against the current binaries ({B}/graphix, {B}/graphix-fuzz; .sh/.py drivers: point them at {B}; .rs repros only under the cargo rule) and decide: FIXED, STILL REPRODUCES (a finding when no open CR already holds it), REGRESSED-DIFFERENTLY (a finding), OBSOLETE (the rule changed or the feature is gone: say how), or OPEN-CR. Judge by the rules as they stand TODAY, not the header's expectation where a ruling changed it. For each FIXED one whose fix looks narrow, try ONE variant (another site of the same rule): a failing variant is a finding. Report only STILL REPRODUCES / REGRESSED / failing variants as findings (cite the old id in the title); put a one-line tally of every file (id: STATUS) in your summary. Keep each run under `timeout -s KILL 60` unless it needs longer. {PROBE_NOTE}""")

# Fable reviewers: the semantic and type-system probes and the core files of
# the checker and the node-walk. Everything else runs on Opus.
FABLE = {
    'x-engine-firing', 'x-sleep-wake', 'x-engine-collections', 'x-engine-seq-errors', 'x-seq-sampling',
    'x-typecheck-generics', 'x-typecheck-order', 'x-typecheck-patterns', 'x-traits-abstract', 'x-dyn-modules',
    'x-check-build', 'x-recursion', 'x-refs', 'x-async-io', 'x-unsafe', 'x-parallel', 'x-prune',
    'c-lib', 'c-node-mod', 'c-callsite', 'c-lambda', 'c-bind', 'c-select-seq', 'c-pattern', 'c-module-traits',
    'c-prune-wake', 'c-analysis-branch', 't-tvar-a', 't-tvar-b', 't-settle', 't-contains-a', 't-contains-b',
    't-fntyp', 't-setops', 't-cast', 't-typ-mod', 't-env', 'f-mod-lowering',
    'a-language', 'a-compiler', 'a-stdlib', 'a-packages',
}

for x in D:
    open(f"{R}/prompts/{x['key']}.md", 'w').write(
        f"YOUR ASSIGNMENT ({'design review' if x['key'].startswith('a-') else 'cross-cutting'}, repository-wide): "
        f"{x['title']}\n\n{x['mission']}\n")
json.dump(D, open(f'{R}/dims.json', 'w'), indent=1)

os.chdir(REPO)
os.makedirs(f'{R}/repro-groups', exist_ok=True)
old = sorted(os.listdir(f"design/review-{PREV['date']}/repro"))
for i in range(GROUPS):
    open(f'{R}/repro-groups/g{i + 1}.txt', 'w').write(
        ''.join(f"design/review-{PREV['date']}/repro/{f}\n" for f in old[i::GROUPS]))
open(f'{R}/open_crs.txt', 'w').write(subprocess.run(['cr', 'list'], capture_output=True, text=True).stdout)

U = json.load(open(f'{R}/units.json'))
keys = sorted((x['key'] for x in D), key=lambda k: not k.startswith('a-')) + [x['key'] for x in sorted(U, key=lambda x: -x['lines'])]
unknown = FABLE - set(keys)
if unknown: raise SystemExit(f'FABLE names no reviewer: {sorted(unknown)}')
ctx = f'{R}/context.md'
if not os.path.exists(ctx): raise SystemExit(f'write {ctx}: what changed since the last review')
head = subprocess.run(['git', 'rev-parse', '--short=9', 'HEAD'], capture_output=True, text=True).stdout.strip()
args = dict(date=DATE, head=head, state=R, work=W, repro=REPRO, prev=PREV, context=' '.join(open(ctx).read().split()),
            fable=sorted(FABLE), order=keys)
json.dump(args, open(f'{R}/args.json', 'w'), indent=1)
nf = len(FABLE)
print(f"dims {len(D)} units {len(U)} reviewers {len(keys)} fable {nf} ({100 * nf // len(keys)}%) head {head}")
